// frontend/src/requests/requests.js

export async function sendRequest({ operation, imageFile, secondImageFile = null, params = {} }) {
  const formData = new FormData();
  formData.append("file", imageFile);

  if (secondImageFile) {
    formData.append("file2", secondImageFile);
  }

  for (const key in params) {
    if (params[key] !== null && params[key] !== undefined) {
      formData.append(key, params[key]);
    }
  }

  try {
    const response = await fetch(`http://127.0.0.1:8000/process/${operation}`, {
      method: "POST",
      body: formData,
    });

    if (!response.ok) {
      throw new Error("Sunucudan geçerli yanıt alınamadı");
    }

    const blob = await response.blob(); // Görseli blob olarak al
    const imageUrl = URL.createObjectURL(blob); // Görseli göstermek için URL oluştur
    return { url: imageUrl };
  } catch (error) {
    console.error("İstek başarısız:", error);
    return null;
  }
}
